const EXTRA_TOWNS = [{"tribe":"יהודה","ref":"יהושע טו, כא","text":"(כא) וַיִּֽהְי֣וּ הֶֽעָרִ֗ים מִקְצֵה֙ לְמַטֵּ֣ה בְנֵֽי־יְהוּדָ֔ה אֶל־גְּב֥וּל אֱד֖וֹם בַּנֶּ֑גְבָּה קַבְצְאֵ֥ל וְעֵ֖דֶר וְיָגֽוּר׃"},{"tribe":"יהודה","ref":"יהושע טו, כב","text":"(כב) וְקִינָ֥ה וְדִימוֹנָ֖ה וְעַדְעָדָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, כג","text":"(כג) וְקֶ֥דֶשׁ וְחָצ֖וֹר וְיִתְנָֽן׃"},{"tribe":"יהודה","ref":"יהושע טו, כד","text":"(כד) זִ֥יף וָטֶ֖לֶם וּבְעָלֽוֹת׃"},{"tribe":"יהודה","ref":"יהושע טו, כה","text":"(כה) וְחָצ֤וֹר&thinsp;׀&thinsp;חֲדַתָּה֙ וּקְרִיּ֔וֹת חֶצְר֖וֹן הִ֥יא חָצֽוֹר׃"},{"tribe":"יהודה","ref":"יהושע טו, כו","text":"(כו) אֲמָ֥ם וּשְׁמַ֖ע וּמוֹלָדָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, כז","text":"(כז) וַחֲצַ֥ר גַּדָּ֛ה וְחֶשְׁמ֖וֹן וּבֵ֥ית פָּֽלֶט׃"},{"tribe":"יהודה","ref":"יהושע טו, כח","text":"(כח) וַחֲצַ֥ר שׁוּעָ֛ל וּבְאֵ֥ר שֶׁ֖בַע וּבִזְיוֹתְיָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, כט","text":"(כט) בַּעֲלָ֥ה וְעִיִּ֖ים וָעָֽצֶם׃"},{"tribe":"יהודה","ref":"יהושע טו, ל","text":"(ל) וְאֶלְתּוֹלַ֥ד וּכְסִ֖יל וְחׇרְמָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, לא","text":"(לא) וְצִֽקְלַ֥ג וּמַדְמַנָּ֖ה וְסַנְסַנָּֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, לב","text":"(לב) וּלְבָא֥וֹת וְשִׁלְחִ֖ים וְעַ֣יִן וְרִמּ֑וֹן כׇּל־עָרִ֛ים עֶשְׂרִ֥ים וָתֵ֖שַׁע וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, לג","text":"(לג) בַּשְּׁפֵלָ֑ה אֶשְׁתָּא֥וֹל וְצׇרְעָ֖ה וְאַשְׁנָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, לד","text":"(לד) וְזָנ֙וֹחַ֙ וְעֵ֣ין גַּנִּ֔ים תַּפּ֖וּחַ וְהָעֵינָֽם׃"},{"tribe":"יהודה","ref":"יהושע טו, לה","text":"(לה) יַרְמוּת֙ וַֽעֲדֻלָּ֔ם שׂוֹכֹ֖ה וַעֲזֵקָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, לו","text":"(לו) וְשַׁעֲרַ֙יִם֙ וַֽעֲדִיתַ֔יִם וְהַגְּדֵרָ֖ה וּגְדֵרֹתָ֑יִם עָרִ֥ים אַרְבַּֽע־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, לז","text":"(לז) צְנָ֥ן וַחֲדָשָׁ֖ה וּמִגְדַּל־גָּֽד׃"},{"tribe":"יהודה","ref":"יהושע טו, לח","text":"(לח) וְדִלְעָ֥ן וְהַמִּצְפֶּ֖ה וְיׇקְתְאֵֽל׃"},{"tribe":"יהודה","ref":"יהושע טו, לט","text":"(לט) לָכִ֥ישׁ וּבׇצְקַ֖ת וְעֶגְלֽוֹן׃"},{"tribe":"יהודה","ref":"יהושע טו, מ","text":"(מ) וְכַבּ֥וֹן וְלַחְמָ֖ס וְכִתְלִֽישׁ׃"},{"tribe":"יהודה","ref":"יהושע טו, מא","text":"(מא) וּגְדֵר֕וֹת בֵּית־דָּג֥וֹן וְנַעֲמָ֖ה וּמַקֵּדָ֑ה עָרִ֥ים שֵׁשׁ־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, מב","text":"(מב) לִבְנָ֥ה וָעֶ֖תֶר וְעָשָֽׁן׃"},{"tribe":"יהודה","ref":"יהושע טו, מג","text":"(מג) וְיִפְתָּ֥ח וְאַשְׁנָ֖ה וּנְצִֽיב׃"},{"tribe":"יהודה","ref":"יהושע טו, מד","text":"(מד) וּקְעִילָ֥ה וְאַכְזִ֖יב וּמָֽרֵאשָׁ֑ה עָרִ֥ים תֵּ֖שַׁע וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, מה","text":"(מה) עֶקְר֥וֹן וּבְנֹתֶ֖יהָ וַחֲצֵרֶֽיהָ׃"},{"tribe":"יהודה","ref":"יהושע טו, מו","text":"(מו) מֵעֶקְר֖וֹן וָיָ֑מָּה כֹּ֛ל אֲשֶׁר־עַל־יַ֥ד אַשְׁדּ֖וֹד וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, מז","text":"(מז) אַשְׁדּ֞וֹד בְּנוֹתֶ֣יהָ וַחֲצֵרֶ֗יהָ עַזָּ֛ה בְּנוֹתֶ֥יהָ וַחֲצֵרֶ֖יהָ עַד־נַ֣חַל מִצְרָ֑יִם וְהַיָּ֥ם (הגבול) [הַגָּד֖וֹל] וּגְבֽוּל׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, מח","text":"(מח) וּבָהָ֑ר שָׁמִ֥יר וְיַתִּ֖יר וְשׂוֹכֹֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, מט","text":"(מט) וְדַנָּ֥ה וְקִרְיַת־סַנָּ֖ה הִ֥יא דְבִֽר׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, נ","text":"(נ) וַעֲנָ֥ב וְאֶשְׁתְּמֹ֖ה וְעָנִֽים׃"},{"tribe":"יהודה","ref":"יהושע טו, נא","text":"(נא) וְגֹ֥שֶׁן וְחֹלֹ֖ן וְגִלֹ֑ה עָרִ֥ים אַחַת־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, נב","text":"(נב) אֲרַ֥ב וְרוּמָ֖ה וְאֶשְׁעָֽן׃"},{"tribe":"יהודה","ref":"יהושע טו, נג","text":"(נג) (וינים) [וְיָנ֥וּם] וּבֵית־תַּפּ֖וּחַ וַאֲפֵֽקָה׃"},{"tribe":"יהודה","ref":"יהושע טו, נד","text":"(נד) וְחֻמְטָ֗ה וְקִרְיַ֥ת אַרְבַּ֛ע הִ֥יא חֶבְר֖וֹן וְצִיעֹ֑ר עָרִ֥ים תֵּ֖שַׁע וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, נה","text":"(נה) מָע֥וֹן&thinsp;׀&thinsp;כַּרְמֶ֖ל וָזִ֥יף וְיוּטָּֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, נו","text":"(נו) וְיִזְרְעֶ֥אל וְיׇקְדְעָ֖ם וְזָנֽוֹחַ׃"},{"tribe":"יהודה","ref":"יהושע טו, נז","text":"(נז) הַקַּ֖יִן גִּבְעָ֣ה וְתִמְנָ֑ה עָרִ֥ים עֶ֖שֶׂר וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, נח","text":"(נח) חַלְח֥וּל בֵּֽית־צ֖וּר וּגְדֽוֹר׃"},{"tribe":"יהודה","ref":"יהושע טו, נט","text":"(נט) וּמַעֲרָ֥ת וּבֵית־עֲנ֖וֹת וְאֶלְתְּקֹ֑ן עָרִ֥ים שֵׁ֖שׁ וְחַצְרֵיהֶֽן׃&nbsp;{פ}"},{"tribe":"יהודה","ref":"יהושע טו, ס","text":"(ס) קִרְיַת־בַּ֗עַל הִ֛יא קִרְיַ֥ת יְעָרִ֖ים וְהָרַבָּ֑ה עָרִ֥ים שְׁתַּ֖יִם וְחַצְרֵיהֶֽן׃&nbsp;{ס}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"},{"tribe":"יהודה","ref":"יהושע טו, סא","text":"(סא) בַּמִּדְבָּ֑ר בֵּ֚ית הָעֲרָבָ֔ה מִדִּ֖ין וּסְכָכָֽה׃"},{"tribe":"יהודה","ref":"יהושע טו, סב","text":"(סב) וְהַנִּבְשָׁ֥ן וְעִיר־הַמֶּ֖לַח וְעֵ֣ין גֶּ֑דִי עָרִ֥ים שֵׁ֖שׁ וְחַצְרֵיהֶֽן׃"},{"tribe":"בנימין","ref":"יהושע יח, כא","text":"(כא) וְהָי֣וּ הֶֽעָרִ֗ים לְמַטֵּ֛ה בְּנֵ֥י בִנְיָמִ֖ן לְמִשְׁפְּחוֹתֵיהֶ֑ם יְרִיח֥וֹ וּבֵית־חׇגְלָ֖ה וְעֵ֥מֶק קְצִֽיץ׃"},{"tribe":"בנימין","ref":"יהושע יח, כב","text":"(כב) וּבֵ֧ית הָעֲרָבָ֛ה וּצְמָרַ֖יִם וּבֵֽית־אֵֽל׃"},{"tribe":"בנימין","ref":"יהושע יח, כג","text":"(כג) וְהָעַוִּ֥ים וְהַפָּרָ֖ה וְעׇפְרָֽה׃"},{"tribe":"בנימין","ref":"יהושע יח, כד","text":"(כד) וּכְפַ֧ר (העמני) [הָעַמֹּנָ֛ה] וְהָעׇפְנִ֖י וָגָ֑בַע עָרִ֥ים שְׁתֵּים־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃"},{"tribe":"בנימין","ref":"יהושע יח, כה","text":"(כה) גִּבְע֥וֹן וְהָרָמָ֖ה וּבְאֵרֽוֹת׃"},{"tribe":"בנימין","ref":"יהושע יח, כו","text":"(כו) וְהַמִּצְפֶּ֥ה וְהַכְּפִירָ֖ה וְהַמֹּצָֽה׃"},{"tribe":"בנימין","ref":"יהושע יח, כז","text":"(כז) וְרֶ֥קֶם וְיִרְפְּאֵ֖ל וְתַרְאֲלָֽה׃"},{"tribe":"בנימין","ref":"יהושע יח, כח","text":"(כח) וְצֵלַ֡ע הָאֶ֜לֶף וְהַיְבוּסִ֨י הִ֤יא יְרוּשָׁלַ֙͏ִם֙ גִּבְעַ֣ת קִרְיַ֔ת עָרִ֥ים אַרְבַּֽע־עֶשְׂרֵ֖ה וְחַצְרֵיהֶ֑ן זֹ֛את נַחֲלַ֥ת בְּנֵֽי־בִנְיָמִ֖ן לְמִשְׁפְּחֹתָֽם׃&nbsp;{פ}"},{"tribe":"שמעון","ref":"יהושע יט, ב","text":"(ב) וַיְהִ֥י לָהֶ֖ם בְּנַחֲלָתָ֑ם בְּאֵֽר־שֶׁ֥בַע וְשֶׁ֖בַע וּמוֹלָדָֽה׃"},{"tribe":"שמעון","ref":"יהושע יט, ג","text":"(ג) וַחֲצַ֥ר שׁוּעָ֛ל וּבָלָ֖ה וָעָֽצֶם׃"},{"tribe":"שמעון","ref":"יהושע יט, ד","text":"(ד) וְאֶלְתּוֹלַ֥ד וּבְת֖וּל וְחׇרְמָֽה׃"},{"tribe":"שמעון","ref":"יהושע יט, ה","text":"(ה) וְצִֽקְלַ֥ג וּבֵית־הַמַּרְכָּב֖וֹת וַחֲצַ֥ר סוּסָֽה׃"},{"tribe":"שמעון","ref":"יהושע יט, ו","text":"(ו) וּבֵ֥ית לְבָא֖וֹת וְשָׁרוּחֶ֑ן עָרִ֥ים שְׁלֹשׁ־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃"},{"tribe":"שמעון","ref":"יהושע יט, ז","text":"(ז) עַ֥יִן&thinsp;׀&thinsp;רִמּ֖וֹן וָעֶ֣תֶר וְעָשָׁ֑ן עָרִ֥ים אַרְבַּ֖ע וְחַצְרֵיהֶֽן׃"},{"tribe":"שמעון","ref":"יהושע יט, ח","text":"(ח) וְכׇל־הַחֲצֵרִ֗ים אֲשֶׁ֤ר סְבִיבוֹת֙ הֶעָרִ֣ים הָאֵ֔לֶּה עַד־בַּ֥עֲלַת בְּאֵ֖ר רָ֣אמַת נֶ֑גֶב זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־שִׁמְע֖וֹן לְמִשְׁפְּחֹתָֽם׃"},{"tribe":"זבולון","ref":"יהושע יט, ט","text":"(ט) מֵחֶ֙בֶל֙ בְּנֵ֣י יְהוּדָ֔ה נַחֲלַ֖ת בְּנֵ֣י שִׁמְע֑וֹן כִּֽי־הָיָ֞ה חֵ֤לֶק בְּנֵֽי־יְהוּדָה֙ רַ֣ב מֵהֶ֔ם וַיִּנְחֲל֥וּ בְנֵֽי־שִׁמְע֖וֹן בְּת֥וֹךְ נַחֲלָתָֽם׃&nbsp;{פ}"},{"tribe":"זבולון","ref":"יהושע יט, י","text":"(י) וַיַּ֙עַל֙ הַגּוֹרָ֣ל הַשְּׁלִישִׁ֔י לִבְנֵ֥י זְבוּלֻ֖ן לְמִשְׁפְּחֹתָ֑ם וַיְהִ֛י גְּב֥וּל נַחֲלָתָ֖ם עַד־שָׂרִֽיד׃"},{"tribe":"זבולון","ref":"יהושע יט, יא","text":"(יא) וְעָלָ֨ה גְבוּלָ֧ם&thinsp;׀&thinsp;לַיָּ֛מָּה וּמַרְעֲלָ֖ה וּפָגַ֣ע בְּדַבָּ֑שֶׁת וּפָגַע֙ אֶל־הַנַּ֔חַל אֲשֶׁ֖ר עַל־פְּנֵ֥י יׇקְנְעָֽם׃"},{"tribe":"זבולון","ref":"יהושע יט, יב","text":"(יב) וְשָׁ֣ב מִשָּׂרִ֗יד קֵ֚דְמָה מִזְרַ֣ח הַשֶּׁ֔מֶשׁ עַל־גְּב֥וּל כִּסְלֹ֖ת תָּבֹ֑ר וְיָצָ֥א אֶל־הַדָּבְרַ֖ת וְעָלָ֥ה יָפִֽיעַ׃"},{"tribe":"זבולון","ref":"יהושע יט, יג","text":"(יג) וּמִשָּׁ֤ם עָבַר֙ קֵ֣דְמָה מִזְרָ֔חָה גִּתָּ֥ה חֵ֖פֶר עִתָּ֣ה קָצִ֑ין וְיָצָ֛א רִמּ֥וֹן הַמְּתֹאָ֖ר הַנֵּעָֽה׃"},{"tribe":"זבולון","ref":"יהושע יט, יד","text":"(יד) וְנָסַ֤ב אֹתוֹ֙ הַגְּב֔וּל מִצְּפ֖וֹן חַנָּתֹ֑ן וְהָיוּ֙ תֹּצְאֹתָ֔יו גֵּ֖י יִפְתַּח־אֵֽל׃"},{"tribe":"זבולון","ref":"יהושע יט, טו","text":"(טו) וְקַטָּ֤ת וְנַהֲלָל֙ וְשִׁמְר֔וֹן וְיִדְאֲלָ֖ה וּבֵ֣ית לָ֑חֶם עָרִ֥ים שְׁתֵּים־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃"},{"tribe":"זבולון","ref":"יהושע יט, טז","text":"(טז) זֹ֛את נַֽחֲלַ֥ת בְּנֵי־זְבוּלֻ֖ן לְמִשְׁפְּחוֹתָ֑ם הֶעָרִ֥ים הָאֵ֖לֶּה וְחַצְרֵיהֶֽן׃&nbsp;{פ}"},{"tribe":"יששכר","ref":"יהושע יט, יז","text":"(יז) לְיִ֨שָּׂשכָ֔ר יָצָ֖א הַגּוֹרָ֣ל הָרְבִיעִ֑י לִבְנֵ֥י יִשָּׂשכָ֖ר לְמִשְׁפְּחוֹתָֽם׃"},{"tribe":"יששכר","ref":"יהושע יט, יח","text":"(יח) וַיְהִ֖י גְּבוּלָ֑ם יִזְרְעֶ֥אלָה וְהַכְּסוּלֹ֖ת וְשׁוּנֵֽם׃"},{"tribe":"יששכר","ref":"יהושע יט, יט","text":"(יט) וַחֲפָרַ֥יִם וְשִׁיאֹ֖ן וַאֲנָחֲרַֽת׃"},{"tribe":"יששכר","ref":"יהושע יט, כ","text":"(כ) וְהָרַבִּ֥ית וְקִשְׁי֖וֹן וָאָֽבֶץ׃"},{"tribe":"יששכר","ref":"יהושע יט, כא","text":"(כא) וְרֶ֧מֶת וְעֵין־גַּנִּ֛ים וְעֵ֥ין חַדָּ֖ה וּבֵ֥ית פַּצֵּֽץ׃"},{"tribe":"יששכר","ref":"יהושע יט, כב","text":"(כב) וּפָגַע֩ הַגְּב֨וּל בְּתָב֤וֹר (ושחצומה) [וְשַׁחֲצִ֙ימָה֙] וּבֵ֣ית שֶׁ֔מֶשׁ וְהָי֛וּ תֹּצְא֥וֹת גְּבוּלָ֖ם הַיַּרְדֵּ֑ן עָרִ֥ים שֵׁשׁ־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃"},{"tribe":"יששכר","ref":"יהושע יט, כג","text":"(כג) זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵי־יִשָּׂשכָ֖ר לְמִשְׁפְּחֹתָ֑ם הֶעָרִ֖ים וְחַצְרֵיהֶֽן׃&nbsp;{פ}"},{"tribe":"אשר","ref":"יהושע יט, כד","text":"(כד) וַיֵּצֵא֙ הַגּוֹרָ֣ל הַחֲמִישִׁ֔י לְמַטֵּ֥ה בְנֵי־אָשֵׁ֖ר לְמִשְׁפְּחוֹתָֽם׃"},{"tribe":"אשר","ref":"יהושע יט, כה","text":"(כה) וַיְהִ֖י גְּבוּלָ֑ם חֶלְקַ֥ת וַחֲלִ֖י וָבֶ֥טֶן וְאַכְשָֽׁף׃"},{"tribe":"אשר","ref":"יהושע יט, כו","text":"(כו) וְאַֽלַמֶּ֥לֶךְ וְעַמְעָ֖ד וּמִשְׁאָ֑ל וּפָגַ֤ע בְּכַרְמֶל֙ הַיָּ֔מָּה וּבְשִׁיח֖וֹר לִבְנָֽת׃"},{"tribe":"אשר","ref":"יהושע יט, כז","text":"(כז) וְשָׁ֨ב מִזְרַ֣ח הַשֶּׁ֘מֶשׁ֮ בֵּ֣ית דָּגֹן֒ וּפָגַ֣ע בִּ֠זְבֻל֠וּן וּבְגֵ֨י יִפְתַּח־אֵ֥ל צָפ֛וֹנָה בֵּ֥ית הָעֵ֖מֶק וּנְעִיאֵ֑ל וְיָצָ֥א אֶל־כָּב֖וּל מִשְּׂמֹֽאל׃"},{"tribe":"אשר","ref":"יהושע יט, כח","text":"(כח) וְעֶבְרֹ֥ן וּרְחֹ֖ב וְחַמּ֣וֹן וְקָנָ֑ה עַ֖ד צִיד֥וֹן רַבָּֽה׃"},{"tribe":"אשר","ref":"יהושע יט, כט","text":"(כט) וְשָׁ֤ב הַגְּבוּל֙ הָרָמָ֔ה וְעַד־עִ֖יר מִבְצַר־צֹ֑ר וְשָׁ֤ב הַגְּבוּל֙ חֹסָ֔ה (ויהיו) [וְהָי֧וּ] תֹצְאֹתָ֛יו הַיָּ֖מָּה מֵחֶ֥בֶל אַכְזִֽיבָה׃"},{"tribe":"אשר","ref":"יהושע יט, ל","text":"(ל) וְעֻמָ֥ה וַאֲפֵ֖ק וּרְחֹ֑ב עָרִ֛ים עֶשְׂרִ֥ים וּשְׁתַּ֖יִם וְחַצְרֵיהֶֽן׃"},{"tribe":"אשר","ref":"יהושע יט, לא","text":"(לא) זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־אָשֵׁ֖ר לְמִשְׁפְּחֹתָ֑ם הֶעָרִ֥ים הָאֵ֖לֶּה וְחַצְרֵיהֶֽן׃&nbsp;{פ}"},{"tribe":"נפתלי","ref":"יהושע יט, לב","text":"(לב) לִבְנֵ֣י נַפְתָּלִ֔י יָצָ֖א הַגּוֹרָ֣ל הַשִּׁשִּׁ֑י לִבְנֵ֥י נַפְתָּלִ֖י לְמִשְׁפְּחֹתָֽם׃"},{"tribe":"נפתלי","ref":"יהושע יט, לג","text":"(לג) וַיְהִ֣י גְבוּלָ֗ם מֵחֵ֨לֶף מֵאֵל֜וֹן בְּצַעֲנַנִּ֗ים וַאֲדָמִ֥י הַנֶּ֛קֶב וְיַבְנְאֵ֖ל עַד־לַקּ֑וּם וַיְהִ֥י תֹצְאֹתָ֖יו הַיַּרְדֵּֽן׃"},{"tribe":"נפתלי","ref":"יהושע יט, לד","text":"(לד) וְשָׁ֨ב הַגְּב֥וּל יָ֙מָּה֙ אַזְנ֣וֹת תָּב֔וֹר וְיָצָ֥א מִשָּׁ֖ם חוּקֹ֑קָה וּפָגַ֨ע בִּזְבֻל֜וּן מִנֶּ֗גֶב וּבְאָשֵׁר֙ פָּגַ֣ע מִיָּ֔ם וּבִ֣יהוּדָ֔ה הַיַּרְדֵּ֖ן מִזְרַ֥ח הַשָּֽׁמֶשׁ׃"},{"tribe":"נפתלי","ref":"יהושע יט, לה","text":"(לה) וְעָרֵ֖י מִבְצָ֑ר הַצִּדִּ֣ים צֵ֔ר וְחַמַּ֖ת רַקַּ֥ת וְכִנָּֽרֶת׃"},{"tribe":"נפתלי","ref":"יהושע יט, לו","text":"(לו) וַאֲדָמָ֥ה וְהָרָמָ֖ה וְחָצֽוֹר׃"},{"tribe":"נפתלי","ref":"יהושע יט, לז","text":"(לז) וְקֶ֥דֶשׁ וְאֶדְרֶ֖עִי וְעֵ֥ין חָצֽוֹר׃"},{"tribe":"נפתלי","ref":"יהושע יט, לח","text":"(לח) וְיִרְאוֹן֙ וּמִגְדַּל־אֵ֔ל חֳרֵ֥ם וּבֵית־עֲנָ֖ת וּבֵ֣ית שָׁ֑מֶשׁ עָרִ֥ים תְּשַֽׁע־עֶשְׂרֵ֖ה וְחַצְרֵיהֶֽן׃"},{"tribe":"נפתלי","ref":"יהושע יט, לט","text":"(לט) זֹ֗את נַחֲלַ֛ת מַטֵּ֥ה בְנֵֽי־נַפְתָּלִ֖י לְמִשְׁפְּחֹתָ֑ם הֶֽעָרִ֖ים וְחַצְרֵיהֶֽן׃&nbsp;{פ}"},{"tribe":"דן","ref":"יהושע יט, מ","text":"(מ) לְמַטֵּ֥ה בְנֵי־דָ֖ן לְמִשְׁפְּחֹתָ֑ם יָצָ֖א הַגּוֹרָ֥ל הַשְּׁבִיעִֽי׃"},{"tribe":"דן","ref":"יהושע יט, מא","text":"(מא) וַיְהִ֖י גְּב֣וּל נַחֲלָתָ֑ם צׇרְעָ֥ה וְאֶשְׁתָּא֖וֹל וְעִ֥יר שָֽׁמֶשׁ׃"},{"tribe":"דן","ref":"יהושע יט, מב","text":"(מב) וְשַׁעֲלַבִּ֥ין וְאַיָּל֖וֹן וְיִתְלָֽה׃"},{"tribe":"דן","ref":"יהושע יט, מג","text":"(מג) וְאֵיל֥וֹן וְתִמְנָ֖תָה וְעֶקְרֽוֹן׃"},{"tribe":"דן","ref":"יהושע יט, מד","text":"(מד) וְאֶלְתְּקֵ֥ה וְגִבְּת֖וֹן וּבַעֲלָֽת׃"},{"tribe":"דן","ref":"יהושע יט, מה","text":"(מה) וִיהֻ֥ד וּבְנֵֽי־בְרַ֖ק וְגַת־רִמּֽוֹן׃"},{"tribe":"דן","ref":"יהושע יט, מו","text":"(מו) וּמֵ֥י הַיַּרְק֖וֹן וְהָרַקּ֑וֹן עִֽם־הַגְּב֖וּל מ֥וּל יָפֽוֹ׃"}];

